    uncheckAutomaticScience: function() {
        var selection = this.getSelectionModel().getSelections();
        var unicodes = selection.map(function(item) { return item.get('unicode'); })
        console.log(selection)
        // console.log(pks.join(''))
        if(selection.length > 0) {
            Ext.Msg.show({
                msg: 
                  '<b>Tem certeza que deseja desmarcar a ciência automática das avaliações?</b> <br>' + unicodes.join('<br>'),
                icon: Ext.MessageBox.WARNING,
                buttons: Ext.Msg.YESNO,
                minWidth: 550,
                scope: this,
                fn: function (b) {
                    if (b == 'no') return;
                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action('ApdPeriodicEvaluationPerformance', 'v1'),
                        method: 'PUT',
                        params: {
                            filter: Ext.encode([
                                {
                                    property: 'pk__in',
                                    value: selection.map(
                                        function(s) { return s.get('pk'); }
                                    )
                                }
                            ]),
                            date_automatica_science: null,
                        },
                        success: function (request) {
                            this.getStore().reload();
                            
                        },
                        failure: function () {
                            Ext.Msg.show({
                                msg: 'Ocorreu um erro tentando processar sua requisição, tente novamente mais tarde.',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK
                            })
                        },
                        scope: this
                    })
                }
            });
        }
        else
            Ext.Msg.show({
                title: 'Status',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione uma avaliação.'
            });
    },

